import { IMAGE_CONFIG, IMAGE_LOADER, ImageLoaderConfig } from '@angular/common';
import { Provider } from '@angular/core';

/** Widths generated by scripts/optimize-images.mjs. */
export const IMAGE_BREAKPOINTS = [320, 480, 768, 1080, 1440, 1920];

/**
 * Local images (`/img/<name>`) map to pre-generated WebP files;
 * Sanity images use the Sanity image CDN (auto format, resized on the fly).
 */
export function floraImageLoader({ src, width }: ImageLoaderConfig): string {
  const w = width ?? 1080;
  if (src.startsWith('https://cdn.sanity.io/')) {
    return `${src}?w=${w}&auto=format&fit=max&q=75`;
  }
  const size = IMAGE_BREAKPOINTS.find((b) => b >= w) ?? IMAGE_BREAKPOINTS[IMAGE_BREAKPOINTS.length - 1];
  return `${src}-${size}.webp`;
}

export const provideFloraImages = (): Provider[] => [
  { provide: IMAGE_LOADER, useValue: floraImageLoader },
  { provide: IMAGE_CONFIG, useValue: { breakpoints: IMAGE_BREAKPOINTS, placeholderResolution: 30, disableImageSizeWarning: true, disableImageLazyLoadWarning: true } },
];
